    {
      "claim": "The destruction of the Old Bridge of Mostar violated the prohibition on attacks against historic monuments under Additional Protocol II to the 1977 Additional Protocols.",
      "reasoning": "Article 16 of Additional Protocol II expressly forbids any acts of hostility directed against historic monuments that constitute cultural heritage, unless such acts are imperatively demanded by military necessity. The Old Bridge was a sixteenth‑century cultural monument; the Trial Chamber found that the HVO’s motive was to sap Muslim morale, not to achieve a decisive military advantage. No evidence shows that its destruction was imperatively demanded by military necessity, so the act breaches Article 16.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "ap_ii",
          "article": "16",
          "quoted_text": "Without prejudice to the provisions of the Hague Convention for the Protection of Cultural Property in the Event of Armed Conflict of 14 May 1954, it is prohibited to commit any acts of hostility directed against historic monuments, works of art or places of worship which constitute the cultural or spiritual heritage of peoples, and to use them in support of the military effort."
        }
      ]
    },
    {
      "claim": "The bridge’s destruction constitutes a war crime of extensive destruction of property not justified by military necessity and carried out wantonly under Article 8(2)(a)(iv) of the Rome Statute.",
      "reasoning": "Article 8(2)(a)(iv) criminalises \"extensive destruction and appropriation of property, not justified by military necessity and carried out unlawfully and wantonly\". The HVO’s tank attack caused the bridge’s collapse, an act of extensive destruction. The Chamber’s finding that the purpose was to demoralise the civilian population demonstrates a wanton motive, and the absence of a clear, indispensable military advantage shows the destruction was not justified by military necessity. Accordingly, the act fulfills each element of the statutory provision.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8(2)(a)(iv)",
          "quoted_text": "Extensive destruction and appropriation of property, not justified by military necessity and carried out unlawfully and wantonly;"
        }
      ]
    },
    {
      "claim": "The destruction of the bridge amounts to devastation of a town not justified by military necessity, violating the laws and customs of war.",
      "reasoning": "The Rome Statute’s war‑crime definition in Article 8(2)(a)(iv) covers \"extensive destruction\" of property when such devastation is not imperatively demanded by the necessities of war. By collapsing the bridge, the HVO isolated a large civilian sector of Mostar, inflicted severe psychological harm, and disrupted essential civilian movement, thereby constituting devastation of the town. The Chamber’s evidence that the bridge’s loss was intended primarily to affect morale, rather than to achieve a concrete military objective, shows the destruction was not indispensable for military operations and therefore unlawful.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8(2)(a)(iv)",
          "quoted_text": "Extensive destruction and appropriation of property, not justified by military necessity and carried out unlawfully and wantonly;"
        }
      ]
    }
  ]
}

